INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','easy','flashcard','What are the HLA associations of Type 1 diabetes mellitus?','["HLA-DR3 and HLA-DR4 (with associated DQ alleles DQ2 and DQ8) confer the greatest susceptibility, accounting for ~90% of genetic risk."]','A','MHC class II molecules present beta-cell autoantigens to CD4+ T helper cells, initiating the autoimmune cascade.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','flashcard','Name three major autoantigens targeted in Type 1 diabetes mellitus.','["Insulin (IAA), Glutamic acid decarboxylase-65 (GAD65), and Islet antigen-2 (IA-2/ICA512). Also: ZnT8 (zinc transporter 8)."]','A','These autoantigens are presented by HLA-DR3/DR4 molecules, triggering autoreactive T-cell responses. Autoantibodies can precede clinical DM by years.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','flashcard','What is insulitis, and in which form of diabetes is it seen?','["Insulitis is lymphocytic (predominantly CD8+ CTL, CD4+ T cells, and macrophages) infiltration of pancreatic islets. It is the hallmark histological lesion of Type 1 diabetes mellitus."]','A','Insulitis reflects the autoimmune attack on beta cells. It is present early in T1DM and is absent in T2DM (which shows amyloid/IAPP deposits instead).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','hard','flashcard','What is the biochemical mechanism by which absolute insulin deficiency causes diabetic ketoacidosis (DKA)?','["Insulin deficiency removes inhibition of hormone-sensitive lipase → massive lipolysis → free fatty acids flood the liver → hepatic ketogenesis (acetoacetate, beta-hydroxybutyrate) exceeds peripheral utilisation → high-anion-gap metabolic acidosis."]','A','Concurrently: glucagon/cortisol/GH rise (counter-regulatory hormones), hepatic gluconeogenesis increases, and glucose uptake falls → hyperglycaemia and osmotic diuresis compound the metabolic crisis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','easy','flashcard','What is the concordance rate for Type 1 DM in monozygotic twins, and what does this imply?','["~35-50% concordance in identical twins, implying a strong but not exclusive genetic component. Environmental triggers (viral infections, gut microbiome, dietary factors) are essential for disease expression."]','A','This contrasts with T2DM concordance (~70-80%), which has greater genetic penetrance. The incomplete concordance in T1DM supports the role of non-genetic triggers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','flashcard','Name the three stages of Type 1 DM according to ADA staging.','["Stage 1: Autoantibody positive + normoglycaemia + normal glucose tolerance. Stage 2: Autoantibodies + dysglycaemia (impaired fasting glucose/IGT). Stage 3: Overt clinical T1DM (symptomatic hyperglycaemia)."]','A','This staging framework reflects the pre-symptomatic window during which immune modulation trials may be effective. Stage 1 and 2 can last years before clinical presentation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','flashcard','Which cytokines from macrophages most directly damage beta cells in Type 1 DM?','["IL-1 beta, TNF-alpha, and IFN-gamma. These induce nitric oxide synthase (iNOS) in beta cells, generating toxic nitric oxide that damages beta-cell DNA and mitochondria."]','A','These cytokines also upregulate MHC class I on beta cells, increasing their visibility to CD8+ CTLs. The combination of direct cytotoxicity and CTL killing drives beta-cell loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','hard','flashcard','What is molecular mimicry in the context of Type 1 DM pathogenesis?','["Molecular mimicry: structural similarity between a foreign antigen (e.g., Coxsackievirus B4 VP1 protein) and a self-antigen (e.g., GAD65) causes cross-reactive T and B cell responses that attack beta cells."]','A','Coxsackievirus B4 is the most strongly implicated viral trigger. The viral infection may also cause direct beta-cell lysis, releasing autoantigens and amplifying the autoimmune response (bystander activation).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','flashcard','What is the Fas-FasL pathway''''s role in beta-cell destruction in T1DM?','["Beta cells express FasL (CD95L). Activated CTLs express Fas (CD95). Beta cells may induce apoptosis in Fas-expressing lymphocytes, but in T1DM, CTL-expressed FasL can also trigger Fas on adjacent beta cells, amplifying apoptosis."]','A','Cytotoxic mechanisms in T1DM: (1) perforin/granzyme B release by CTLs, (2) Fas-FasL apoptosis, (3) cytokine-mediated (NO, TNF-alpha). Multiple parallel pathways make single-target therapies insufficient.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','easy','flashcard','What is the gross morphological appearance of the pancreas at the time of diagnosis of Type 1 DM?','["The pancreas may appear grossly normal or slightly reduced in size. Microscopically: selective loss of beta cells with relative preservation of alpha, delta, and PP cells; islets appear reduced in size and may show lymphocytic infiltration (insulitis) early, or ghost islets (depleted) later."]','A','By the time of clinical presentation, ~80-90% of beta-cell mass is typically destroyed. Alpha cells (glucagon) and delta cells (somatostatin) are largely spared.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','easy','flashcard','What are the two fundamental pathophysiological defects in Type 2 diabetes mellitus?','["1. Peripheral insulin resistance (skeletal muscle, adipose, liver) — the initiating defect. 2. Progressive beta-cell failure — inability to secrete sufficient insulin to overcome resistance."]','A','Initially, beta cells compensate by hypersecretion (hyperinsulinaemia). Over years, beta cells fail due to glucotoxicity, lipotoxicity, amyloid (IAPP) deposition, and ER stress.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','flashcard','Describe the histological appearance of the pancreas in Type 2 DM.','["Amyloid (IAPP/amylin) deposition in and around islets (present in >90%, Congo red positive with apple-green birefringence), reduced beta-cell mass (~50% reduction at diagnosis), no insulitis."]','A','IAPP is co-secreted with insulin by beta cells. Misfolded IAPP forms oligomeric toxic species and fibrils. The absence of insulitis distinguishes T2DM histology from T1DM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','flashcard','What is the role of adipose tissue inflammation in T2DM insulin resistance?','["Obesity-driven macrophage infiltration into adipose tissue (crown-like structures) releases pro-inflammatory cytokines (TNF-alpha, IL-1 beta, IL-6, MCP-1) that activate JNK and IKK-beta/NF-kB signalling in hepatocytes and myocytes, causing serine phosphorylation of IRS-1 and blocking insulin signalling."]','A','This creates a chronic low-grade inflammatory state. Elevated circulating FFAs from dysfunctional adipose tissue amplify insulin resistance via the Randle cycle and ceramide/diacylglycerol-mediated PKC activation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','hard','flashcard','What is the TCF7L2 gene and why is it the strongest common genetic risk factor for T2DM?','["TCF7L2 (transcription factor 7-like 2) is a Wnt signalling transcription factor involved in GLP-1 production from intestinal L-cells and beta-cell proliferation/survival. The risk allele (rs7903146) impairs GLP-1 secretion and beta-cell gene expression, reducing insulin secretory capacity."]','A','TCF7L2 risk variants confer ~1.4-fold increased T2DM risk per allele and are the most replicated GWAS finding in T2DM across multiple ethnicities.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','easy','flashcard','What is glucotoxicity in T2DM and how does it cause progressive beta-cell failure?','["Chronic hyperglycaemia (glucotoxicity) causes beta-cell dysfunction via: oxidative stress (superoxide production from glucose oxidation), ER stress (UPR activation from excessive insulin folding demand), mitochondrial dysfunction, and epigenetic reprogramming — collectively reducing beta-cell mass and insulin secretory capacity."]','A','Glucotoxicity creates a vicious cycle: hyperglycaemia → beta-cell damage → less insulin → more hyperglycaemia. This explains why early glycaemic control can preserve beta-cell function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','flashcard','What is the incretin effect and how is it impaired in T2DM?','["The incretin effect: oral glucose stimulates gut L-cells to secrete GLP-1 and K-cells to secrete GIP, augmenting glucose-stimulated insulin secretion by ~50-70%. In T2DM: GLP-1 secretion is reduced and GIP receptor signalling is impaired in beta cells, blunting the incretin effect."]','A','GLP-1 receptor agonists (exenatide, liraglutide, semaglutide) pharmacologically restore incretin signalling. They also delay gastric emptying, suppress glucagon, and promote satiety.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','flashcard','Define MODY and name the gene responsible for MODY-3, the most common form.','["MODY (Maturity-Onset Diabetes of the Young): monogenic, autosomal dominant diabetes with onset typically <25 years, no ketosis, and initially responsive to sulphonylureas. MODY-3 is caused by HNF-1 alpha mutations — the most common form (~70% of MODY)."]','A','MODY subtypes: MODY-1 (HNF-4 alpha), MODY-2 (glucokinase — GCK, mild stable hyperglycaemia), MODY-3 (HNF-1 alpha), MODY-4 (IPF-1/PDX-1), MODY-5 (HNF-1 beta). Genetic testing is essential for correct classification and management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','hard','flashcard','What is the Randle (glucose-fatty acid) cycle and its relevance to T2DM?','["The Randle cycle: in skeletal muscle, elevated FFA oxidation (from obesity/lipolysis) raises intramitochondrial acetyl-CoA/CoA and NADH/NAD+ ratios, inhibiting pyruvate dehydrogenase (blocking glucose oxidation) and raises citrate which inhibits phosphofructokinase (blocking glycolysis), reducing glucose uptake."]','A','This FFA-glucose competition means that in obese T2DM, the muscle preferentially burns fat, worsening glucose clearance. FFA also activates diacylglycerol-PKC theta pathway, directly serine-phosphorylating IRS-1.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','flashcard','What is the pathological mechanism of beta-cell apoptosis in T2DM caused by IAPP?','["Misfolded IAPP monomers form toxic oligomers that disrupt beta-cell membranes (membrane permeabilisation), activate caspase-mediated apoptosis, trigger ER stress (UPR — CHOP pathway), and cause mitochondrial dysfunction, collectively leading to progressive beta-cell death."]','A','IAPP oligomers (not fibrils) are the primary toxic species. They insert into lipid bilayers, forming pores. Amyloid fibril deposition in islets is a marker of cumulative beta-cell damage in established T2DM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','easy','flashcard','Name four common features of the metabolic syndrome (IDF criteria).','["Central obesity (waist circumference >94cm men, >80cm women in Europeans) PLUS ≥2 of: (1) Triglycerides ≥1.7mmol/L, (2) HDL <1.0 (men) or <1.3 (women) mmol/L, (3) Blood pressure ≥130/85 mmHg, (4) Fasting glucose ≥5.6mmol/L or T2DM."]','A','Metabolic syndrome confers 5x increased T2DM risk and 3x cardiovascular disease risk. The unifying pathophysiology is insulin resistance driven by central/visceral adiposity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','easy','flashcard','What is the earliest morphological lesion of diabetic nephropathy on light microscopy?','["Glomerular basement membrane (GBM) thickening and mesangial matrix expansion — detectable within 2-5 years of diabetes onset, before clinical proteinuria."]','A','These changes are driven by non-enzymatic glycosylation of GBM proteins (collagen IV, laminin) altering their charge and structure, and by TGF-beta-driven mesangial cell matrix overproduction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','flashcard','Describe Kimmelstiel-Wilson nodules and their pathological significance.','["Kimmelstiel-Wilson nodules: PAS-positive, laminated, acellular deposits of mesangial matrix (collagen IV, fibronectin) arranged in a nodular pattern at the periphery of glomeruli. They are pathognomonic for diabetic nephropathy."]','A','KW nodules represent advanced focal mesangial expansion. They appear late in diabetic nephropathy (diffuse glomerulosclerosis precedes nodular). The differential includes nodular mesangial lesions of light-chain deposition disease and amyloidosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','flashcard','What distinguishes background (non-proliferative) from proliferative diabetic retinopathy?','["Background DR: microaneurysms (earliest sign), dot-blot haemorrhages, hard exudates (lipid), soft exudates (cotton-wool spots = retinal infarcts). Proliferative DR: neovascularisation (new vessels on disc or elsewhere), vitreous haemorrhage, tractional retinal detachment."]','A','The transition is driven by retinal ischaemia causing VEGF overexpression. VEGF-driven neovascularisation leads to fragile vessels that bleed and cause fibrosis/tractional detachment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','hard','flashcard','Explain the polyol pathway and its contribution to diabetic complications.','["In hyperglycaemia, excess glucose is reduced to sorbitol by aldose reductase (consuming NADPH), then oxidised to fructose by sorbitol dehydrogenase (consuming NAD+). Consequences: sorbitol accumulation (osmotic stress in lens → cataracts), NADPH depletion (reduced glutathione regeneration → oxidative stress), NAD+/NADH imbalance."]','A','The polyol pathway is particularly active in tissues where glucose uptake is insulin-independent (lens, nerves, kidney, retina) — exactly the tissues prone to diabetic complications.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','easy','flashcard','What is ''''diabetic autonomic neuropathy'''' and name four clinical manifestations?','["Diabetic autonomic neuropathy affects unmyelinated autonomic fibres. Manifestations: (1) Gastroparesis (delayed gastric emptying, nausea, vomiting), (2) Orthostatic hypotension (loss of cardiovascular autonomic control), (3) Erectile dysfunction, (4) Neurogenic bladder (urinary retention/incontinence), (5) Diabetic diarrhoea, (6) Cardiac arrhythmias (loss of heart rate variability)."]','A','Autonomic neuropathy significantly impairs quality of life. Painless myocardial infarction can occur due to loss of cardiac pain perception — a life-threatening consequence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','flashcard','What is the mechanism of AGE (advanced glycation end-product) formation and its pathological effects?','["AGEs form by non-enzymatic glycation: glucose reacts with amino groups on proteins (Maillard reaction) forming reversible Schiff bases → Amadori products → irreversible AGEs (cross-linked proteins). Effects: (1) Cross-linking of GBM, collagen IV reducing elasticity; (2) RAGE (receptor for AGE) activation → NF-kB → inflammation/VEGF; (3) Trapping of plasma proteins in vessel walls."]','A','HbA1c is an Amadori product on haemoglobin — a clinically measurable index of cumulative glycation. AGE accumulation in tissues is cumulative and not fully reversible with glucose control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','flashcard','What is the pathological basis of the ''''capsule drop'''' lesion in diabetic nephropathy?','["Capsule drop (also called fibrin cap): accumulation of plasma proteins (fibrin, immunoglobulins) between the parietal epithelium and Bowman''''s capsule, or as homogeneous material overlying peripheral glomerular capillaries. PAS-positive and fibronectin-rich. Indicates severe glomerular capillary leakage."]','A','Both capsule drops and fibrin caps are features of advanced diabetic nephropathy, along with KW nodules and diffuse glomerulosclerosis. They reflect severe endothelial dysfunction and hyperfiltration damage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','hard','flashcard','What causes ''''diabetic foot'''' and describe the pathological mechanisms involved?','["Diabetic foot results from the combination of: (1) Peripheral neuropathy (loss of pain sensation → unperceived trauma and pressure), (2) Peripheral vascular disease/ischaemia (reduced healing), (3) Immunodeficiency (impaired neutrophil function in hyperglycaemia → infection). Collectively: non-healing ulcers, osteomyelitis, and gangrene."]','A','The neuropathic component causes Charcot joints and plantar ulcers (pressure points). The ischaemic component causes distal digital gangrene. Mixed aetiology is most common clinically.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','flashcard','What is the ''''afferent AND efferent arteriolar hyalinosis'''' sign in diabetic nephropathy and why is it diagnostically important?','["Hyaline arteriolosclerosis affecting BOTH afferent AND efferent glomerular arterioles is pathognomonic of diabetic nephropathy. Plasma proteins insude into arteriolar walls, replacing smooth muscle with PAS-positive hyaline material."]','A','In hypertensive nephrosclerosis, only the afferent arteriole is hyalinised. The presence of efferent arteriolar hyalinosis distinguishes diabetic from hypertensive nephropathy on renal biopsy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','easy','flashcard','What is microalbuminuria and what does it indicate pathologically in diabetes?','["Microalbuminuria: urinary albumin excretion 30-300 mg/day (or 20-200 micg/min, or albumin:creatinine ratio 3-30 mg/mmol). It indicates early glomerular injury with loss of the GBM negative charge barrier (loss of heparan sulphate proteoglycans), allowing small amounts of albumin to pass."]','A','Microalbuminuria is the earliest CLINICAL indicator of diabetic nephropathy and predicts progressive renal decline. It is also an independent cardiovascular risk factor. ACE inhibitors/ARBs reduce intraglomerular pressure and slow progression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','easy','flashcard','What are the diagnostic autoantibodies in Hashimoto thyroiditis?','["Anti-TPO (anti-thyroid peroxidase/anti-microsomal) antibodies — present in >90% of cases; Anti-thyroglobulin antibodies — present in ~60%. Anti-TPO is more sensitive and specific."]','A','TPO catalyses iodide oxidation and thyroglobulin iodination (organification step). Anti-TPO antibodies can activate complement (type II hypersensitivity) and mediate ADCC, contributing to follicular destruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','flashcard','What are the three hallmark histological features of Hashimoto thyroiditis?','["1. Extensive lymphocytic infiltration with germinal centre formation. 2. Hurthle (oxyphilic) cell metaplasia — follicular epithelium replaced by cells with abundant granular eosinophilic cytoplasm (mitochondrial accumulation). 3. Follicular atrophy and interstitial fibrosis."]','A','Hurthle cells (also called oncocytes or Askanazy cells) are enlarged follicular cells with abundant pink granular cytoplasm due to mitochondrial hyperplasia. They are a response to injury in Hashimoto and also occur in nodular goitre and follicular adenoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','flashcard','What is myxoedema and what is its pathological mechanism?','["Myxoedema: non-pitting oedema of the skin (and internal organs) in severe hypothyroidism caused by accumulation of glycosaminoglycans (hyaluronic acid and chondroitin sulphate) in the dermis. T3/T4 are needed to maintain normal GAG turnover; deficiency impairs GAG catabolism."]','A','The water-binding capacity of accumulated GAGs causes the characteristic ''''doughy'''' non-pitting oedema. Affects face (puffy facies), tongue (macroglossia), and subcutaneous tissues. The term ''''myxoedema'''' is also used as a clinical synonym for severe hypothyroidism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','hard','flashcard','Describe cretinism (congenital hypothyroidism) — causes and clinical features.','["Causes: maternal iodine deficiency (most common worldwide), thyroid agenesis/dysgenesis, dyshormonogenesis (e.g., TPO mutations). Features: severe intellectual disability (irreversible — brain requires T3 for development), growth retardation/dwarfism, coarse facies, macroglossia, umbilical hernia, deaf-mutism, spastic diplegia."]','A','Neonatal screening (TSH/T4 heel-prick) allows early treatment that prevents permanent intellectual disability. The neurological damage in iodine-deficiency cretinism reflects the critical window of fetal brain development requiring maternal thyroid hormones.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','easy','flashcard','What is Riedel thyroiditis and how does it differ from other thyroiditis types?','["Riedel thyroiditis: dense, keloid-like fibrosis replacing thyroid tissue and extending into surrounding neck structures (trachea, oesophagus, carotid sheaths, parathyroids). Part of the IgG4-related disease spectrum. The thyroid is rock-hard (''iron-hard''), fixed, and mimics carcinoma or lymphoma."]','A','Unlike Hashimoto (lymphocytic, intrathyroidal) or de Quervain (granulomatous, self-limited), Riedel shows fibro-inflammatory infiltrate extending BEYOND the thyroid capsule. Elevated serum IgG4 and IgG4+ plasma cells on biopsy confirm IgG4-RD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','flashcard','What is the biochemical profile of primary vs. secondary hypothyroidism?','["Primary hypothyroidism (thyroid failure): elevated TSH + low free T4. Secondary hypothyroidism (pituitary failure): low TSH + low free T4. Tertiary (hypothalamic failure): low TRH → low TSH + low free T4 (same as secondary)."]','A','The key discriminator: in primary, the intact pituitary senses low T4 and compensates by raising TSH. TSH elevation precedes free T4 decline (subclinical hypothyroidism = high TSH + normal free T4). TRH stimulation test can differentiate secondary from tertiary.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','flashcard','What is subacute (de Quervain) thyroiditis and what are its histological and clinical features?','["Subacute granulomatous thyroiditis: follows viral URTI (mumps, influenza, coxsackievirus). Histology: granulomatous inflammation with multinucleated giant cells engulfing colloid. Clinical: painful tender thyroid, elevated ESR, triphasic course (hyperthyroid → hypothyroid → euthyroid recovery)."]','A','The pain distinguishes it from other thyroiditis. Viral destruction of follicles releases preformed thyroid hormones (transient hyperthyroid phase). As stores deplete and follicles are damaged, hypothyroidism follows. Most recover fully within months.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','hard','flashcard','What complication of Hashimoto thyroiditis confers the greatest malignancy risk?','["Primary thyroid lymphoma — virtually always B-cell (diffuse large B-cell lymphoma or MALT/marginal zone lymphoma). Hashimoto thyroiditis confers a 67-80x increased risk of thyroid lymphoma compared to the general population."]','A','The mechanism: chronic lymphocytic infiltration creates a lymphoid-rich environment that can undergo malignant transformation. The MALT lymphoma may develop from chronic antigen-driven B-cell stimulation, similar to H. pylori-associated gastric MALT lymphoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','flashcard','What is the significance of Hurthle cell change in thyroid pathology?','["Hurthle (oxyphilic) cell change: follicular cells acquire abundant granular eosinophilic cytoplasm due to mitochondrial proliferation. Seen in Hashimoto thyroiditis (metaplastic), Hurthle cell adenoma, and Hurthle cell carcinoma. Hurthle cell carcinoma is a subtype of follicular carcinoma with poorer prognosis."]','A','Hurthle cell (oncocytic) carcinoma: lacks PAX8-PPARG rearrangements typical of follicular carcinoma; has disomies of multiple chromosomes and TERT promoter mutations in aggressive cases. Does NOT take up radioiodine (reduced sodium-iodide symporter expression).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','easy','flashcard','In iodine-deficient regions, what is the most common cause of hypothyroidism worldwide?','["Iodine deficiency is the most common worldwide cause of hypothyroidism and goitre. Insufficient iodine → inadequate thyroid hormone synthesis → compensatory TSH rise → thyroid gland hyperplasia → goitre. If prolonged, hypothyroidism and cretinism result."]','A','The WHO estimates 2 billion people are iodine-deficient worldwide. Universal salt iodisation has reduced but not eliminated this problem. In iodine-replete developed countries, Hashimoto thyroiditis is the most common cause.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','easy','flashcard','What is the pathogenic mechanism of Graves disease?','["TSH receptor-stimulating immunoglobulins (TSI/TRAb) — IgG autoantibodies — bind and chronically stimulate the TSH receptor on follicular cells, mimicking TSH action, causing unregulated thyroid hormone synthesis and diffuse goitre."]','A','TSI is a type II hypersensitivity (stimulatory). Unlike Hashimoto, which destroys the gland, Graves stimulates it. TSI crosses the placenta and can cause neonatal thyrotoxicosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','flashcard','Describe the gross and microscopic appearance of the thyroid in Graves disease.','["Gross: diffusely enlarged, beefy-red, vascular thyroid. Microscopic: diffuse follicular hyperplasia with tall columnar epithelium, papillary infoldings (no fibrovascular cores), peripheral scalloping of pale colloid (rapid resorption), increased vascularity, and lymphocytic infiltrate."]','A','Pre-operatively, iodine (Lugol solution) is given to reduce vascularity (Wolf-Chaikoff effect). The lymphocytic infiltrate reflects the autoimmune nature — Graves and Hashimoto share pathogenic mechanisms (both involve anti-TSH receptor antibodies, but of different functional types).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','flashcard','What are the nuclear features of papillary thyroid carcinoma (PTC) on histology?','["Orphan Annie eye nuclei: clear, empty-appearing nuclei (ground-glass chromatin) with irregular contours, longitudinal nuclear grooves, and intranuclear cytoplasmic pseudoinclusions. These are the diagnostic nuclear features on cytology/histology."]','A','Orphan Annie eye nuclei: named after the blank-eyed cartoon character. The appearance is due to redistribution of chromatin and intranuclear cytoplasmic inclusions. These features allow diagnosis even in the follicular variant of PTC where papillary architecture is absent.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','hard','flashcard','What is the most common genetic alteration in papillary thyroid carcinoma and its clinical significance?','["BRAF V600E mutation (~45% of PTC): constitutively activates BRAF kinase → ERK/MAPK signalling → uncontrolled proliferation. Associated with more aggressive behaviour: extrathyroidal extension, lymph node metastasis, higher recurrence, resistance to radioiodine."]','A','BRAF V600E testing guides prognosis and treatment. Vemurafenib (BRAF inhibitor) is used in BRAF V600E-mutant advanced thyroid cancer. RET/PTC rearrangements (20-30%) are an alternative driver, more common in radiation-associated PTC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','easy','flashcard','How is follicular thyroid carcinoma (FTC) distinguished from follicular adenoma?','["Capsular invasion and/or vascular invasion on histology — the ONLY reliable distinguishing criteria. Minimally invasive FTC: focal capsular penetration only. Widely invasive FTC: extensive capsular and/or vascular invasion. Cytology (FNA) CANNOT distinguish — requires surgical excision."]','A','Molecular markers (THADA fusions, DICER1 mutations, PAX8-PPARG rearrangements) can support FTC diagnosis. FTC spreads haematogenously (lung, bone) unlike PTC (lymph nodes). Distant metastases are functional (radioiodine-avid).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','flashcard','What is medullary thyroid carcinoma (MTC) and what is its tumour marker?','["MTC arises from parafollicular C-cells (neural crest origin) that normally secrete calcitonin. Calcitonin (and CEA) are tumour markers. Histology: nests/sheets of polygonal/spindle cells with amyloid stroma (Congo red+, derived from procalcitonin). 25% hereditary (RET mutations)."]','A','Calcitonin levels are used for diagnosis, post-operative monitoring, and family screening in MEN 2. CEA parallels disease burden. Amyloid stroma is pathognomonic. MTC does NOT concentrate radioiodine (C-cells lack sodium-iodide symporter).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','flashcard','Describe thyroid storm (thyrotoxic crisis) — precipitants, features, and emergency management.','["Precipitants: surgery, infection, trauma, iodinated contrast in uncontrolled hyperthyroidism. Features: hyperpyrexia (>38.5C), severe tachycardia/AF, neuropsychiatric (agitation, psychosis, coma), GI (vomiting, diarrhoea). Management: PTU (blocks synthesis AND T4→T3 conversion), beta-blocker (propranolol), Lugol iodine (1h after PTU — Wolf-Chaikoff), dexamethasone, cooling."]','A','Burch-Wartofsky score ≥45 = thyroid storm. PTU is preferred over carbimazole in storm as it also inhibits peripheral T4→T3 conversion via deiodinase inhibition. Lugol iodine must be given AFTER PTU to prevent iodine being used as substrate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','hard','flashcard','What is the WHO classification of thyroid carcinoma, listing the four main types in order of frequency?','["1. Papillary thyroid carcinoma (PTC) — ~85%, best prognosis. 2. Follicular thyroid carcinoma (FTC) — ~10%, haematogenous spread. 3. Medullary thyroid carcinoma (MTC) — ~3-5%, C-cell origin. 4. Anaplastic/undifferentiated carcinoma — ~1-2%, most lethal."]','A','5-year survival: PTC ~98%; FTC ~85%; MTC ~75%; Anaplastic ~5%. Risk factors: radiation exposure (PTC), iodine excess/deficiency (FTC), RET mutations (MTC), radiation + pre-existing differentiated carcinoma (anaplastic).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','flashcard','What is the pathological mechanism of pretibial myxoedema in Graves disease?','["TSH receptor-stimulating antibodies activate TSH receptors expressed on dermal fibroblasts in the pretibial skin, stimulating excessive hyaluronic acid (GAG) synthesis, causing indurated, non-pitting skin plaques over the anterior shins."]','A','Pretibial myxoedema is paradoxically a feature of hyperthyroid Graves disease (NOT hypothyroidism). The name ''''myxoedema'''' is misleading — it is a localised effect of TSI on skin fibroblasts. Also associated with thyroid acropachy (periosteal new bone formation over phalanges) and exophthalmos.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','easy','flashcard','What mutation drives anaplastic thyroid carcinoma and what is its prognosis?','["TP53 mutations are the most common driver in anaplastic thyroid carcinoma (ATC), often superimposed on pre-existing PTC or FTC (''''dedifferentiation''''). TERT promoter mutations and PI3K/AKT pathway alterations also contribute. Prognosis: median survival 3-6 months, essentially 100% mortality."]','A','ATC is WHO stage IVA-C at presentation by definition. Histology: markedly pleomorphic giant cells, spindle cells, squamoid cells. No radioiodine uptake. Surgery is rarely curative. BRAF V600E-mutant ATC may respond to combined BRAF/MEK inhibition (dabrafenib + trametinib).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','easy','flashcard','List the causes of Cushing syndrome in order of frequency.','["1. Iatrogenic (exogenous glucocorticoids) — most common overall. 2. Cushing disease (pituitary ACTH-secreting adenoma) — most common endogenous cause (~70%). 3. Ectopic ACTH secretion (small cell lung cancer, carcinoid) — ~15%. 4. Primary adrenal adenoma/carcinoma — ~15%."]','A','Cushing disease (pituitary) vs. syndrome (any cause): remember, ''''disease'''' = pituitary cause only; ''''syndrome'''' = any cause of glucocorticoid excess. The high-dose dexamethasone suppression test (8mg) distinguishes pituitary (suppresses) from ectopic/adrenal (does not suppress).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','flashcard','What are the adrenal morphological findings in ACTH-dependent vs. ACTH-independent Cushing syndrome?','["ACTH-dependent (pituitary or ectopic): bilateral adrenal cortical hyperplasia (both glands enlarged, cortex thickened). ACTH-independent (adrenal adenoma/carcinoma): unilateral tumour + contralateral cortical atrophy (suppressed ACTH causes atrophy of non-neoplastic cortex)."]','A','In bilateral macronodular adrenal hyperplasia (BMAH): rare autonomous cortisol production from bilateral nodules; ACTH is suppressed. In PPNAD (Carney complex): bilateral micronodular disease with paradoxical dexamethasone stimulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','flashcard','What is Waterhouse-Friderichsen syndrome?','["Bilateral adrenal haemorrhage and necrosis causing acute adrenocortical insufficiency, classically in meningococcal (Neisseria meningitidis) septicaemia. DIC causes microvascular thrombosis in adrenal vasculature. Clinical: septic shock, purpuric rash, and adrenal crisis (hypotension, hypoglycaemia)."]','A','Other causes of bilateral adrenal haemorrhage: DIC from any cause, anticoagulation, trauma, neonatal stress (birth asphyxia). The adrenal glands are vulnerable due to their rich blood supply entering via arteries but draining via a single central vein — susceptible to venous outflow obstruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','hard','flashcard','What are the Weiss criteria for distinguishing adrenocortical carcinoma from adenoma?','["Weiss criteria (≥3 = carcinoma): (1) >5 mitoses/50 HPF, (2) atypical mitoses, (3) clear cells <25% of tumour, (4) diffuse architecture >33%, (5) necrosis, (6) venous invasion, (7) sinusoidal invasion, (8) capsular invasion, (9) nuclear grade 3-4. Weight >100g and size >6cm also favour malignancy."]','A','The modified Weiss score, Helsinki score, and reticulin algorithm are also used. Loss of parafibromin (HRPT2) and steroidogenic factor-1 (SF-1) expression helps. ACC has a 5-year survival of ~35-55% in resectable disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','easy','flashcard','What is the biochemical diagnosis of Conn syndrome (primary hyperaldosteronism)?','["Elevated aldosterone-to-renin ratio (ARR) — screening test (ARR >30 with aldosterone >15ng/dL). Confirmatory: fludrocortisone suppression test, saline infusion test, captopril challenge. Imaging: adrenal CT. Lateralisation: adrenal vein sampling (AVS) — gold standard to distinguish unilateral adenoma from bilateral hyperplasia."]','A','Conn syndrome: hypertension + hypokalaemia + suppressed renin + elevated aldosterone. Cause in ~35%: solitary aldosterone-producing adenoma (Conn adenoma) — surgically curable. ~65%: bilateral adrenal hyperplasia — treated with mineralocorticoid antagonist (spironolactone/eplerenone).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','flashcard','What is autoimmune Addison disease and what are its histological features?','["Autoimmune adrenalitis: autoimmune destruction of the adrenal cortex (all three zones) while sparing the medulla. Autoantibodies target 21-hydroxylase (CYP21A2). Histology: lymphocytic infiltration, progressive cortical cell loss, and fibrosis. Cortex is reduced to a thin rim; medulla is preserved."]','A','70-80% of Addison disease in developed countries. Associated with APS-1 (AIRE mutation: hypoparathyroidism + Addison + mucocutaneous candidiasis) and APS-2 (Schmidt syndrome: Addison + T1DM + Hashimoto). Presents with hyperpigmentation (elevated ACTH/MSH), hypotension, fatigue, hyponatraemia, hyperkalaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','flashcard','What is the 21-hydroxylase deficiency (most common CAH) biochemical signature?','["Elevated 17-hydroxyprogesterone (17-OHP) — the substrate that cannot be converted to 11-deoxycortisol. Also: elevated ACTH (from loss of cortisol feedback), elevated androgens (DHEA, androstenedione — shunted from blocked pathway), low/normal cortisol, and in salt-wasting form: low aldosterone + high renin."]','A','Neonatal screening: 17-OHP on heel-prick. Classic salt-wasting form presents with life-threatening adrenal crisis in neonatal period + virilisation of female genitalia. Simple virilising form: no salt-wasting. Non-classic form: premature adrenarche, oligomenorrhoea, hirsutism in adults.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','hard','flashcard','What is Nelson syndrome and how does it arise?','["Nelson syndrome: aggressive expansion of a pituitary corticotroph (ACTH-secreting) adenoma after bilateral adrenalectomy for Cushing disease. Loss of cortisol feedback removes restraint on the adenoma, causing rapid growth, very high ACTH levels, and hyperpigmentation (ACTH has MSH-like activity)."]','A','Prevention: some advocate pituitary irradiation before adrenalectomy. Features: headache, visual field defects (chiasmal compression), markedly elevated ACTH, and bronze skin pigmentation from ACTH-driven melanocyte stimulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','flashcard','Describe the histological appearance of an adrenocortical adenoma causing Cushing syndrome.','["Yellow-orange gross appearance (high lipid content). Microscopically: composed predominantly of clear cells (lipid-rich, resembling zona fasciculata) with some compact eosinophilic cells. Encapsulated. Rim of atrophic non-neoplastic cortex. No necrosis or atypical mitoses (contrasting with carcinoma)."]','A','The yellow-orange colour reflects cholesterol and lipid stores (steroidogenesis precursors). Adenoma size typically <50g, <4cm. The normal adrenal cortex in the contralateral gland is atrophic due to ACTH suppression by tumour-derived cortisol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','easy','flashcard','What is the zonation of the adrenal cortex and which hormones does each zone produce?','["Zone Glomerulosa (outermost): mineralocorticoids (aldosterone) — regulated by renin-angiotensin-aldosterone system. Zone Fasciculata (middle, largest): glucocorticoids (cortisol) — regulated by ACTH. Zone Reticularis (innermost): sex steroids (DHEA, androstenedione) — regulated by ACTH. Medulla: catecholamines (adrenaline/noradrenaline)."]','A','Mnemonic: GFR from outside to inside — Glomerulosa→Fasciculata→Reticularis. Only the zona glomerulosa expresses aldosterone synthase (CYP11B2); other zones cannot make aldosterone. ACTH regulates fasciculata and reticularis but NOT glomerulosa (regulated by angiotensin II and potassium).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','easy','flashcard','What is a phaeochromocytoma and from which cells does it arise?','["Phaeochromocytoma: catecholamine-secreting tumour arising from chromaffin cells of the adrenal medulla. Chromaffin cells are neural crest-derived, neuroendocrine cells that synthesise and store adrenaline (epinephrine) and noradrenaline (norepinephrine)."]','A','Extra-adrenal chromaffin tumours (from sympathetic ganglia) are called paragangliomas. Both phaeochromocytoma and paraganglioma are now grouped as PPGL (phaeochromocytoma/paraganglioma).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','flashcard','State the ''''rule of 10s'''' for phaeochromocytoma.','["10% bilateral, 10% extra-adrenal (paraganglioma), 10% malignant, 10% in children, 10% familial (hereditary). Note: modern data suggests hereditary cases may be up to 25-30% with germline testing."]','A','Hereditary PPGL syndromes: MEN 2A/2B (RET), VHL (VHL), NF1 (NF1), SDH mutations (SDHA, SDHB, SDHC, SDHD), MAX mutations. All newly diagnosed PPGLs should be considered for germline testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','flashcard','Describe the Zellballen pattern of phaeochromocytoma on histology.','["Zellballen (cell balls): characteristic nested/alveolar architecture — clusters/nests of chief (principal) cells with abundant pale/granular cytoplasm, surrounded by sustentacular cells (S100+) and delicate fibrovascular septa. Chief cells stain positive for chromogranin A, synaptophysin, and NSE."]','A','Paragangliomas show identical Zellballen architecture. The sustentacular cells (S100+) form a scaffold around the nests. In malignant PPGLs, the Zellballen pattern may be lost, with diffuse sheets replacing the nested pattern.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','hard','flashcard','What is the most sensitive and specific biochemical test for phaeochromocytoma?','["Plasma or urinary fractionated metanephrines (metanephrine + normetanephrine). Sensitivity >95%, specificity ~85-89%. Metanephrines are produced continuously within tumour cells by catechol-O-methyltransferase (COMT), even between episodic catecholamine secretion, making them more reliable than catecholamines."]','A','False positives: tricyclic antidepressants, methyldopa, sympathomimetics, labetalol (interferes with normetanephrine assay). Confirmatory imaging: CT/MRI adrenals; functional: 123I-MIBG scintigraphy or 68Ga-DOTATATE PET-CT for paraganglioma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','easy','flashcard','How is malignancy defined in phaeochromocytoma?','["Malignancy in PPGL is defined SOLELY by the presence of metastases at sites where chromaffin tissue does not normally exist (liver, lung, bone, distant lymph nodes). No histological features (necrosis, atypia, vascular invasion) reliably predict malignancy."]','A','The PASS score (≥4) and GAPP score attempt histological risk stratification but have limitations. SDHB mutation is the strongest predictor of malignant behaviour (~70% malignancy rate in SDHB-mutant PPGLs). 5-year survival in metastatic PPGL: ~50%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','flashcard','What are the clinical features of a phaeochromocytoma crisis?','["Paroxysmal or sustained: severe hypertension, pounding headache, profuse diaphoresis, palpitations (tachycardia or reflex bradycardia), pallor, and anxiety/panic. Triad: headache + sweating + palpitations in a hypertensive patient has ~90% predictive value for PPGL."]','A','Crises can be precipitated by: tumour manipulation/surgery, contrast agents, certain drugs (dopamine antagonists, opioids, tricyclics, beta-blockers — block vasodilatory beta-2 receptors, unmasking alpha-mediated vasoconstriction). Pre-operative alpha-blockade (phenoxybenzamine) is mandatory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','flashcard','Which SDH subunit mutation carries the highest risk of malignant paraganglioma?','["SDHB (succinate dehydrogenase subunit B) mutations confer the highest malignancy risk (~70% malignancy rate vs. ~5% for SDHD). SDHB-mutant PPGLs are often extra-adrenal, retroperitoneal/abdominal, and metastasize to bone, liver, and lung."]','A','SDH complex II (of the mitochondrial electron transport chain): SDHA, SDHB, SDHC, SDHD subunits. Loss-of-function mutations impair complex II activity → succinate accumulation → pseudohypoxia (succinate inhibits PHD enzymes → HIF-1 alpha stabilisation → VEGF → angiogenesis/tumourigenesis).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','hard','flashcard','What is neuroblastoma and how does it differ from phaeochromocytoma?','["Neuroblastoma: malignant tumour of neuroblasts (undifferentiated neural crest cells) — most common extracranial solid tumour of childhood. Arises from adrenal medulla or sympathetic ganglia. Unlike phaeochromocytoma (mature chromaffin cells), neuroblastoma is undifferentiated/immature. N-MYC amplification = poor prognosis. Homer-Wright pseudorosettes are pathognomonic."]','A','Neuroblastoma spectrum: neuroblastoma (undifferentiated) → ganglioneuroblastoma (partially differentiated) → ganglioneuroma (fully differentiated, benign). Elevated urinary VMA and HVA (vanillylmandelic acid and homovanillic acid — catecholamine metabolites) are tumour markers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','flashcard','Describe the gross morphology of a resected phaeochromocytoma.','["Large, well-circumscribed tumour (typically 3-5cm, >100g). Cut surface: grey-white to reddish-brown with haemorrhage, cystic change, focal necrosis, and a variegated appearance. Brown colour due to oxidised catecholamines (chromaffin reaction with potassium dichromate). Encapsulated."]','A','The chromaffin reaction (brown colour with chromium salts) is the basis for the name ''''chromaffin cell.'''' This reaction reflects oxidation of catecholamines (adrenaline/noradrenaline) by chromate ions to form brownish polymers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','easy','flashcard','What is the relationship between VHL disease and phaeochromocytoma?','["VHL (von Hippel-Lindau) disease: autosomal dominant, caused by loss-of-function VHL gene mutation (chromosome 3p25). VHL protein is part of an E3 ubiquitin ligase that degrades HIF-1 alpha. Loss → constitutive HIF-1 alpha → VEGF/EPO upregulation. PPGLs occur in ~20-25% of VHL, typically bilateral, noradrenergic (normetanephrine-predominant)."]','A','VHL type 2 has highest PPGL risk: 2A (haemangioblastoma + PPGL, low RCC risk), 2B (all features + high RCC risk), 2C (PPGL only). VHL-associated PPGLs rarely metastasise but require careful surveillance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','easy','flashcard','What are the most common types of pituitary adenoma in order of frequency?','["1. Prolactinoma (lactotroph) — ~30%, most common. 2. Non-functioning adenoma (gonadotroph) — ~25-30%. 3. GH-secreting somatotroph adenoma — ~15-20%. 4. ACTH-secreting corticotroph — ~10-15%. 5. TSH-secreting thyrotroph — rare (<2%)."]','A','Microadenoma: <10mm; macroadenoma: >10mm. Most pituitary adenomas are sporadic. Monomorphous WHO classification (2022): based on transcription factor expression (Pit-1, SF-1, T-pit, ER alpha).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','flashcard','What visual field defect does a pituitary macroadenoma classically cause and why?','["Bitemporal hemianopia — loss of the peripheral temporal visual fields in both eyes. Caused by upward expansion of the adenoma compressing the decussating nasal fibres of the optic chiasm, which carry temporal field information from each eye."]','A','The optic chiasm lies ~1cm above the pituitary fossa. Lateral extension of macroadenoma into the cavernous sinus causes cranial nerve palsies (CN III, IV, V1, V2, VI). Downward extension can invade the sphenoid sinus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','flashcard','What molecular mechanism is responsible for GH-secreting adenomas in 40% of cases?','["Activating mutations in GNAS1 (gsp oncogene) — the gene encoding the Gs-alpha subunit of trimeric G-proteins. Mutation at Arg201 or Gln227 prevents GTP hydrolysis → constitutively active Gs-alpha → persistent adenylyl cyclase activation → raised cAMP → somatotroph proliferation and autonomous GH secretion."]','A','This is analogous to the RAS oncogene mechanism but for heterotrimeric G-proteins. The same GNAS1 mutations occur in thyroid adenomas, Leydig cell tumours, and McCune-Albright syndrome (mosaic activating GNAS1 mutation causing polyostotic fibrous dysplasia, precocious puberty, and cafe-au-lait spots).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','hard','flashcard','From where does craniopharyngioma arise and what are its two histological types?','["Craniopharyngioma arises from Rathke''''s pouch remnants (embryonic oral ectoderm). Two types: (1) Adamantinomatous — children and young adults, CTNNB1 (beta-catenin) mutations, wet keratin, cholesterol crystals, calcification; (2) Papillary — adults, BRAF V600E mutation, solid/papillary, no calcification, better prognosis."]','A','Adamantinomatous craniopharyngioma: ''''machine oil'''' cyst contents (cholesterol-rich fluid), eggshell calcification on CT, calcification pathognomonic. Recurrence is high. Papillary type: more circumscribed, less adherent, BRAF inhibition may be therapeutic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','easy','flashcard','What is the pathogenesis of central diabetes insipidus and how does it present?','["Central DI: deficiency of ADH (vasopressin) from posterior pituitary/hypothalamus due to: tumour (craniopharyngioma, metastases), trauma, surgery, autoimmune (lymphocytic hypophysitis), or idiopathic. ADH normally inserts aquaporin-2 in collecting ducts. Deficiency: inability to concentrate urine → polyuria (>3L/day, specific gravity <1.005, osmolality <300 mOsm/kg), polydipsia, hypernatraemia if fluid intake is inadequate."]','A','Water deprivation test: urine osmolality fails to rise with dehydration (unlike primary polydipsia). Desmopressin (ADH analogue) administration: urine osmolality rises in central DI; no response in nephrogenic DI (V2 receptor or AQP2 defect).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','flashcard','What is acromegaly and what are its pathological cardiovascular consequences?','["Acromegaly: GH hypersecretion in adults (after epiphyseal fusion) causing: coarsening of features (prognathism, supraorbital bossing), enlarged hands/feet, macroglossia, organomegaly. Cardiovascular: acromegalic cardiomyopathy — biventricular hypertrophy, diastolic/systolic dysfunction — leading cause of death. Also: hypertension, arrhythmias."]','A','GH acts via IGF-1 (produced by liver): IGF-1 mediates most growth effects and is the diagnostic/monitoring marker. Treatment: transsphenoidal surgery (first-line), somatostatin analogues (octreotide/lanreotide), GH receptor antagonist (pegvisomant), dopamine agonists (if co-secreting prolactin).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','flashcard','What is Sheehan syndrome and what hormones are typically lost in sequence?','["Sheehan syndrome: ischaemic pituitary necrosis from post-partum haemorrhage and hypotension. The pituitary enlarges during pregnancy (lactotroph hyperplasia); hypotension during haemorrhage causes ischaemia of the adenohypophysis. Hormone loss sequence: GH (earliest) → LH/FSH → TSH → ACTH (most resistant). Failure to lactate (prolactin deficiency) is often the first symptom."]','A','Complete Sheehan: panhypopituitarism. Partial: variable hormone deficiencies. Treatment: lifelong hormone replacement (cortisol and T4 are essential; oestrogen for menstrual function; GH optional). Posterior pituitary (DI) is uncommon as its blood supply is separate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','hard','flashcard','What are the histological subtypes of corticotroph adenomas causing Cushing disease?','["Densely granulated corticotroph adenoma (ACTH-rich, basophilic): most common, strong PAS positivity (glycoprotein hormones), strongly ACTH-immunoreactive, Crooke hyaline change (perinuclear keratin accumulation in normal corticotrophs from cortisol excess). Sparsely granulated: less common. Silent corticotroph adenoma: ACTH-immunoreactive but clinically non-functional."]','A','Crooke hyaline change: normal corticotrophs in the anterior pituitary accumulate intermediate filaments (keratin) in the cytoplasm in response to sustained glucocorticoid excess. This perinuclear ring of hyaline material is seen in Cushing syndrome from any cause.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','flashcard','What is lymphocytic hypophysitis and who is most commonly affected?','["Lymphocytic hypophysitis: autoimmune inflammatory destruction of the anterior pituitary, predominantly in women in the third trimester of pregnancy or post-partum. Presents with: headache, visual disturbance (pituitary enlargement), and hypopituitarism (ACTH deficiency first, then TSH, prolactin elevated early). IgG4-related disease can also cause this."]','A','Histology: diffuse lymphocytic and plasma cell infiltration of the pituitary with destruction of normal adenohypophysis. MRI shows a homogeneous, symmetrically enlarged pituitary with uniform enhancement — distinguishes from adenoma. Treatment: glucocorticoids; spontaneous remission occurs in some.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','easy','flashcard','What is the ''''pituitary incidentaloma'''' and how should it be managed?','["Pituitary incidentaloma: pituitary lesion found incidentally on neuroimaging performed for another reason. Prevalence: ~10-20% in autopsy series. Most are non-functioning microadenomas. Management: (1) biochemical screen for hormonal excess (IGF-1, prolactin, 24h UFC, IGFBP-3); (2) formal visual field testing for macroadenoma; (3) MRI follow-up at 6-12 months then annually."]','A','Indications for surgery: chiasmal compression, progressive visual loss, apoplexy, or evidence of hormonal excess (except prolactinoma — dopamine agonist first). Prolactinoma is the ONE pituitary adenoma type treated medically first regardless of size.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','easy','flashcard','What is the most common cause of primary hyperparathyroidism?','["Solitary parathyroid chief cell adenoma (~80-85%). Other causes: multiple adenomas (~4%), four-gland chief cell hyperplasia (~15%), parathyroid carcinoma (<1%). Chief cell adenoma is encapsulated with a rim of compressed normal parathyroid tissue."]','A','Primary hyperparathyroidism is the most common cause of hypercalcaemia in the outpatient setting (vs. malignancy = most common inpatient cause). Most cases today are asymptomatic, detected incidentally on routine calcium testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','flashcard','Describe osteitis fibrosa cystica — what is it and what causes it?','["Osteitis fibrosa cystica (Von Recklinghausen disease of bone): severe hyperparathyroidism causes osteoclastic bone resorption via PTH-driven RANKL upregulation on osteoblasts → RANK on osteoclasts → osteoclast activation. Features: subperiosteal resorption (radial border of middle phalanges), brown tumours (haemorrhagic osteoclastic lesions), bone cysts, ''''salt-and-pepper'''' skull, pathological fractures."]','A','Brown tumours are NOT neoplasms — they are reactive giant cell-rich haemorrhagic lesions from osteoclastic resorption and repair, containing haemosiderin (hence brown). They are identical microscopically to giant cell tumours of bone, requiring clinical context to distinguish.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','flashcard','What is secondary hyperparathyroidism and what causes it in chronic kidney disease?','["Secondary hyperparathyroidism: compensatory four-gland parathyroid hyperplasia in response to chronic hypocalcaemia. In CKD: (1) phosphate retention → calcium-phosphate binding → hypocalcaemia; (2) loss of renal 1-alpha-hydroxylase → reduced 1,25-(OH)2D3 (calcitriol) → decreased intestinal calcium absorption and reduced direct PTH suppression."]','A','Treatment: phosphate binders, calcium supplements, calcitriol or vitamin D analogues (paricalcitol), and cinacalcet (calcimimetic — allosteric activator of calcium-sensing receptor, sensitises parathyroid glands to calcium, reducing PTH). Parathyroidectomy for refractory cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','hard','flashcard','How is parathyroid carcinoma diagnosed and what molecular marker supports the diagnosis?','["Parathyroid carcinoma: diagnosed by histological evidence of: dense fibrous bands traversing the tumour, vascular invasion, capsular invasion, perineural invasion, and high mitotic rate. Clinically: markedly elevated calcium (>14mg/dL) and PTH (often >3x normal). Loss of parafibromin (HRPT2/CDC73 gene, chromosome 1q31) by immunostaining is highly suggestive."]','A','CDC73/HRPT2 germline mutations cause hyperparathyroidism-jaw tumour syndrome (HPT-JT) — parathyroid carcinoma + fibro-osseous jaw tumours. Loss of parafibromin staining by IHC is >95% sensitive for carcinoma. All parathyroid carcinomas should be tested for CDC73 mutations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','easy','flashcard','State the MEN 1 triad and the gene responsible.','["MEN 1 (Wermer syndrome): (1) Parathyroid hyperplasia/adenoma (>90%) — most common and earliest. (2) Pancreatic islet tumours (gastrinoma most common, also insulinoma, VIPoma, glucagonoma). (3) Pituitary adenoma (prolactinoma most common). Gene: MENIN (tumour suppressor, chromosome 11q13)."]','A','MENIN interacts with the MLL histone methyltransferase complex, controlling H3K4 methylation and gene expression. Loss of MENIN → de-repression of oncogenes (CCND1 etc.) and loss of cell cycle control. Autosomal dominant; ''''two-hit'''' tumour suppressor model.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','flashcard','What is the calcium-sensing receptor (CaSR) and what diseases result from its mutation?','["CaSR: G-protein coupled receptor on parathyroid cells and renal tubules that detects extracellular calcium. Activation → suppresses PTH. Loss-of-function CaSR mutation → familial hypocalciuric hypercalcaemia (FHH) — mild hypercalcaemia, low urinary calcium, mildly elevated PTH. Gain-of-function CaSR mutation → autosomal dominant hypocalcaemia/hypoparathyroidism."]','A','FHH (CaSR loss-of-function) is benign and does NOT require parathyroidectomy — a critical distinction from primary hyperparathyroidism. Clue: calcium:creatinine clearance ratio <0.01. Neonatal severe hyperparathyroidism occurs with homozygous CaSR loss-of-function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','flashcard','What is pseudohypoparathyroidism (PHP) and how does it present?','["PHP: PTH end-organ resistance due to Gs-alpha (GNAS1) loss-of-function mutation. Type 1a (Albright hereditary osteodystrophy): hypocalcaemia + hyperphosphataemia + elevated PTH (reactive) + short stature + round facies + shortened 4th/5th metacarpals + subcutaneous calcifications. PTH infusion fails to raise urinary cAMP (diagnostic)."]','A','Pseudopseudohypoparathyroidism: AHO phenotype without the biochemical abnormalities — due to paternal inheritance of the same GNAS1 mutation (imprinting: GNAS1 is maternally imprinted in kidney, so paternal-only expression means maternal mutation → PHP, paternal mutation → PPHP).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','hard','flashcard','What is tertiary hyperparathyroidism and how does it differ from secondary?','["Tertiary hyperparathyroidism: autonomous (unregulated) PTH secretion from hyperplastic parathyroid glands that developed in secondary hyperparathyroidism, persisting even after the primary stimulus (hypocalcaemia) is corrected (e.g., post-renal transplant). Both PTH AND calcium are elevated (vs. secondary: elevated PTH but low/normal calcium)."]','A','Treatment: parathyroidectomy (3.5-gland or total with autotransplantation). Tertiary hyperparathyroidism develops because some hyperplastic cells acquire somatic mutations (e.g., loss of CaSR expression) making them autonomous. Cinacalcet may delay but not prevent the need for surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','flashcard','What are the radiological signs of primary hyperparathyroidism on plain X-ray?','["1. Subperiosteal bone resorption — radial border of middle phalanges (pathognomonic). 2. ''''Salt-and-pepper'''' skull (granular-appearing calvarium). 3. Brown tumours (lytic expansile lesions). 4. Bone cysts. 5. Chondrocalcinosis (calcium pyrophosphate deposition). 6. Nephrocalcinosis/nephrolithiasis on abdominal films."]','A','These findings characterise osteitis fibrosa cystica — now rare due to early biochemical detection. Subperiosteal resorption of the radial (outer) border of the index/middle finger middle phalanges is the MOST SPECIFIC radiological sign of hyperparathyroidism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','easy','flashcard','What is hypoparathyroidism and what are its clinical manifestations of hypocalcaemia?','["Hypoparathyroidism: low PTH → hypocalcaemia + hyperphosphataemia. Most common cause: iatrogenic (post-thyroidectomy/parathyroidectomy). Clinical: Chvostek sign (facial nerve tap → facial muscle twitch), Trousseau sign (carpal spasm with BP cuff inflated >systolic for 3 min), tetany, laryngospasm, seizures, QT prolongation, and papilloedema."]','A','Long-term hypoparathyroidism: basal ganglia calcification (Fahr syndrome appearance), cataract, dry skin, brittle nails. Treatment: calcium supplements + active vitamin D (calcitriol — bypasses the 1-alpha-hydroxylase step that requires PTH). Recombinant PTH (teriparatide) for refractory cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','easy','flashcard','What is Whipple''''s triad for insulinoma?','["Whipple''''s triad: (1) Symptoms of hypoglycaemia (fasting or exercise-induced — sweating, tremor, confusion, seizure), (2) documented hypoglycaemia (blood glucose <2.2mmol/L at time of symptoms), (3) relief of symptoms with glucose administration."]','A','Insulinoma confirmation: elevated insulin (>3 mcIU/mL) + elevated C-peptide (distinguishes from exogenous insulin) + elevated proinsulin during supervised 72-hour fast. 90% of insulinomas are benign, solitary, <2cm, within the pancreas.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','flashcard','What are the clinical features of Zollinger-Ellison syndrome (gastrinoma)?','["ZES features: (1) recurrent, multiple, atypical peptic ulcers (duodenum, jejunum, post-anastomotic), (2) diarrhoea (gastric acid inactivates pancreatic enzymes, damages intestinal mucosa), (3) elevated fasting serum gastrin (>200pg/mL), (4) gastric acid hypersecretion (BAO >15mEq/h). Secretin stimulation test: paradoxical gastrin rise (>120pg/mL increase)."]','A','~25% of gastrinomas are in MEN 1. The gastrinoma triangle (Passaro): junction cystic+CBD superiorly, 2nd/3rd duodenum inferiorly, head/neck pancreas medially — contains ~65% of gastrinomas. Proton pump inhibitors control acid hypersecretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','flashcard','Describe the pathological features and clinical syndrome of VIPoma.','["VIPoma (Verner-Morrison/WDHA syndrome): VIP-secreting tumour (usually pancreatic tail) causing: Watery Diarrhoea (>3L/day, secretory — persists with fasting), Hypokalaemia (massive stool K+ loss), Achlorhydria (VIP inhibits gastric acid). VIP activates adenylyl cyclase in intestinal enterocytes → raised cAMP → Cl- secretion and Na+ absorption inhibition."]','A','Laboratory: very low serum potassium, metabolic alkalosis (bicarbonate loss initially, then metabolic acidosis with severe loss), normal or low gastrin (distinguished from ZES). Diagnosis: elevated plasma VIP levels. Treatment: somatostatin analogues (octreotide) to control diarrhoea pending surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','hard','flashcard','What is necrolytic migratory erythema (NME) and which tumour causes it?','["NME is pathognomonic of glucagonoma. It is a blistering, crusting, migrating erythematous rash affecting the perineum, groin, lower abdomen, and extremities. Caused by: amino acid deficiency (glucagon drives catabolism), zinc deficiency, and essential fatty acid depletion — collectively causing keratinocyte necrolysis."]','A','Glucagonoma ''''4D syndrome'''': Dermatitis (NME), Diabetes mellitus (glucagon opposes insulin), DVT/VTE (hypercoagulable), and Depression (mechanism unclear). Also: weight loss, anaemia, glossitis. Glucagonoma is usually in pancreatic tail and often malignant at diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','easy','flashcard','What is chromogranin A (CgA) and what is its role in neuroendocrine tumour diagnosis?','["Chromogranin A: acidic secretory protein co-stored with hormones in dense-core secretory granules of neuroendocrine cells. Elevated in >80% of pancreatic NETs (functional and non-functional) and other NETs. Used for: diagnosis (elevated levels), staging (levels correlate with tumour burden), and monitoring treatment response."]','A','CgA is cleaved to generate bioactive peptides (pancreastatin, vasostatin) that inhibit insulin secretion and vasoconstriction. False positives: PPI use (elevates gastrin → enterochromaffin-like cell hyperplasia → elevated CgA), renal failure, inflammatory bowel disease. Synaptophysin: another IHC marker (presynaptic vesicle membrane protein).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','flashcard','Describe the histological appearance of a well-differentiated pancreatic neuroendocrine tumour (PNET).','["Well-differentiated PNET: organoid nesting, trabecular ribbons, gyriform, or solid growth patterns. Uniform round cells with moderate amphophilic cytoplasm and round nuclei with ''''salt-and-pepper'''' (finely stippled, evenly distributed) chromatin pattern. Low mitotic rate. IHC: synaptophysin+, chromogranin A+, CD56+. Ki-67 index determines grade (G1 <3%, G2 3-20%, G3 >20%)."]','A','The salt-and-pepper chromatin (stippled, finely granular nuclear chromatin) is characteristic of all neuroendocrine tumours and reflects the dispersed chromatin pattern of neuroendocrine cell nuclei. Poorly differentiated NEC (neuroendocrine carcinoma) resembles small cell or large cell carcinoma and has ki-67 typically >55%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','flashcard','What is the gastrinoma triangle (Passaro''''s triangle) and why is it clinically important?','["Gastrinoma triangle: anatomical region bounded by (1) junction of cystic duct and common bile duct (superior), (2) junction of 2nd and 3rd parts of duodenum (inferior), (3) junction of pancreatic head and neck (medial). ~65-70% of gastrinomas (including duodenal wall tumours) arise in this triangle."]','A','Knowing the gastrinoma triangle guides surgical exploration in ZES. Duodenal gastrinomas (small, submucosal) are often missed on CT but found by duodenotomy and transillumination. Intraoperative ultrasound helps localise pancreatic gastrinomas. Endoscopic ultrasound (EUS) is the most sensitive pre-operative imaging.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','hard','flashcard','What is somatostatinoma syndrome?','["Somatostatinoma inhibitory triad: (1) Diabetes mellitus (somatostatin inhibits insulin and glucagon secretion), (2) Cholelithiasis/gallstones (somatostatin inhibits CCK, reducing gallbladder contraction and bile flow), (3) Steatorrhoea (somatostatin inhibits pancreatic enzyme and bicarbonate secretion). Also: hypochlorhydria, diarrhoea."]','A','Somatostatinoma is rare (~1% of PNETs), usually in pancreatic head or duodenum (duodenal somatostatinomas associated with NF1 and Von Recklinghausen disease). Most are malignant at diagnosis (liver metastases). The inhibitory triad results from somatostatin suppressing all GI regulatory hormones.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','flashcard','What is the WHO 2019 grading system for pancreatic neuroendocrine neoplasms?','["WHO 2019: Well-differentiated NETs: G1 (ki-67 <3%, <2 mitoses/2mm²), G2 (ki-67 3-20%, 2-20 mitoses/2mm²), G3 (ki-67 >20%, >20 mitoses — well-differentiated but high-grade). Poorly differentiated neuroendocrine carcinoma (NEC): small cell or large cell type, ki-67 typically >55%, always high-grade (G3 by definition). MiNEN: mixed neuroendocrine-non-neuroendocrine neoplasm."]','A','The key distinction: G3 NET (well-differentiated, ki-67 >20%) has BETTER prognosis than NEC (poorly differentiated, ki-67 typically >55%). They respond differently to treatment — G3 NETs may respond to somatostatin analogues; NECs require platinum-based chemotherapy (cisplatin + etoposide).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','easy','flashcard','What is the most common pancreatic neuroendocrine tumour in MEN 1 and how does it present?','["Gastrinoma is the most clinically significant pancreatic NET in MEN 1 (~40-60% prevalence). In MEN 1, gastrinomas are characteristically: multiple, small (<1cm), and duodenal wall (>50%). They cause Zollinger-Ellison syndrome and are the leading cause of morbidity/mortality in MEN 1 after parathyroid disease."]','A','Unlike sporadic gastrinoma (usually solitary, pancreatic), MEN 1 gastrinomas are multiple and duodenal. Surgical cure is rare in MEN 1 gastrinoma. Insulinoma is the 2nd most common MEN 1 pancreatic NET (~10-20%), occurs in younger patients, and is usually solitary and resectable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','easy','flashcard','What gene is mutated in MEN 1 and what is its function?','["MENIN gene (chromosome 11q13) — a tumour suppressor. Menin protein is a scaffold protein in the MLL/SET1 histone H3K4 methyltransferase complex, regulating gene transcription through chromatin remodelling. Loss of menin causes derepression of growth-promoting genes (e.g., CCND1/cyclin D1)."]','A','MEN 1 follows the two-hit tumour suppressor model: germline MENIN mutation (one hit) + somatic loss of heterozygosity (second hit) in target tissues. Germline testing identifies carriers; surveillance begins from age 5 with annual biochemical testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','flashcard','What is the classic triad of MEN 2A (Sipple syndrome)?','["MEN 2A: (1) Medullary thyroid carcinoma (MTC) — virtually 100%, penetrance; (2) Phaeochromocytoma — ~50%, often bilateral; (3) Primary hyperparathyroidism — ~20%, usually mild four-gland hyperplasia. Caused by activating RET mutations, most commonly at codon 634 (Cys634Arg) in exon 11."]','A','MTC is the first and most penetrant manifestation of MEN 2A. Prophylactic thyroidectomy based on RET mutation risk stratification prevents MTC. Phaeochromocytoma must be excluded BEFORE thyroid or parathyroid surgery to prevent intraoperative hypertensive crisis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','flashcard','What distinguishes MEN 2B from MEN 2A?','["MEN 2B additional features (not in MEN 2A): Marfanoid body habitus (tall, slender, arachnodactyly), mucosal neuromas (lips, tongue, eyelids — ''''bumpy lips'''' sign), GI ganglioneuromatosis (constipation, megacolon). MEN 2B has NO parathyroid disease. Most aggressive MTC (onset in infancy/early childhood). RET codon 918 (M918T) mutation."]','A','MEN 2B RET codon 918 mutation is the highest-risk mutation — thyroidectomy recommended within first 6 months of life. The marfanoid habitus resembles Marfan syndrome but without lens subluxation or cardiovascular anomalies. Mucosal neuromas on lips/tongue are pathognomonic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','hard','flashcard','What is the RET proto-oncogene and how do its mutations cause MEN 2?','["RET encodes a transmembrane receptor tyrosine kinase activated by GDNF family ligands (GDNF, neurturin, artemin, persephin). Activating (gain-of-function) RET mutations in MEN 2 cause: constitutive kinase activation → uncontrolled proliferation of C-cells (MTC), adrenal chromaffin cells (phaeochromocytoma), and parathyroid cells."]','A','RET mutation genotype-phenotype: Codon 634 → MEN 2A (highest hyperparathyroidism risk); Codon 918 → MEN 2B (most aggressive MTC); Exon 10 codons (609,611,618,620) → MEN 2A or FMTC. Loss-of-function RET mutations → Hirschsprung disease (failure of neural crest migration to bowel). RET/PTC rearrangements → PTC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','easy','flashcard','What is familial medullary thyroid carcinoma (FMTC) and how is it distinguished from MEN 2?','["FMTC: autosomal dominant, hereditary MTC without phaeochromocytoma or hyperparathyroidism across ≥4 affected family members in ≥2 generations. Caused by RET mutations (often exon 8, 10, 11, or 13-16 codons). Less aggressive than MEN 2B MTC."]','A','FMTC is now considered a subtype of MEN 2A with very low penetrance of non-thyroid features. Surveillance: annual calcitonin and neck ultrasound. The primary risk is MTC — phaeochromocytoma and hyperparathyroidism screening should still be performed regularly as penetrance is not zero.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','flashcard','What is Carney complex and which gene is mutated?','["Carney complex: PRKAR1A gene mutation (chromosome 17q24) — encodes regulatory subunit 1A of protein kinase A (PKA). Loss → constitutive PKA activity → cAMP-independent signalling. Features: spotty skin pigmentation (lentigines), cardiac myxomas (atrial — can cause stroke/embolism), primary pigmented nodular adrenocortical disease (PPNAD — bilateral micronodular Cushing), testicular large cell calcifying Sertoli cell tumour, and pituitary GH adenoma."]','A','PPNAD in Carney complex: paradoxically, dexamethasone STIMULATES cortisol secretion (Liddle''''s test — positive paradoxical response). Bilateral adrenal micronodules (pigmented with brown/black lipofuscin). Distinct from MEN syndromes: no MTC, phaeochromocytoma, or pancreatic NETs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','flashcard','What surveillance protocol is recommended for MEN 1 gene carriers?','["Annual biochemical screening from age 5: (1) Serum calcium + PTH (parathyroid — most common manifestation); (2) Fasting glucose + insulin (insulinoma — can occur in childhood); (3) Fasting gastrin + secretin stimulation (gastrinoma); (4) Prolactin + IGF-1 (pituitary). Imaging: MRI pituitary every 3-5 years; CT/MRI pancreas every 1-3 years; EUS for pancreatic NETs."]','A','Biochemical screening detects MEN 1 manifestations before symptoms or imaging changes. Genetic testing of first-degree relatives of MEN 1 patients is essential — 50% chance of inheriting the mutation. Penetrance of parathyroid disease approaches 100% by age 50.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','hard','flashcard','What is the molecular mechanism linking MENIN loss to tumourigenesis in MEN 1?','["Menin maintains MLL/SET1 complex activity → H3K4me3 (active chromatin mark) at tumour suppressor gene loci (CDKN1B/p27, CDKN2C/p18). Loss of menin → reduced H3K4 methylation → silencing of p27 and p18 → loss of G1 cell cycle restraint → uncontrolled proliferation of parathyroid, pituitary, and pancreatic cells."]','A','Menin also interacts with JunD (repressing AP-1-mediated transcription), SMAD3 (TGF-beta signalling), and nuclear receptors. The loss of menin-mediated tumour suppression is cell-type-specific — different tissues undergo transformation at different rates, explaining the variable penetrance of MEN 1 manifestations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','flashcard','Name the specific RET codon mutations and their associated MEN phenotype.','["Codon 634 (Cys634Arg/Tyr/Ser/Gly/Trp) — MEN 2A, highest hyperparathyroidism penetrance; Codon 918 (Met918Thr) — MEN 2B, most aggressive MTC, earliest onset; Codon 883 (Ala883Phe) — MEN 2B variant; Exon 10 codons 609, 611, 618, 620 — MEN 2A or FMTC; Codon 768, 790, 791, 804 — lower-risk FMTC/MEN 2A (moderate risk)."]','A','ATA/ETA risk stratification: Highest risk (codon 918) → thyroidectomy within 6 months of life; High risk (634, 883) → by age 5; Moderate risk (all others) → by age 5-10 or calcitonin-guided. This genotype-phenotype correlation allows personalised prophylactic surgery timing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','easy','flashcard','What is multiple endocrine neoplasia type 4 (MEN 4) and how does it differ from MEN 1?','["MEN 4: caused by CDKN1B mutations (p27/Kip1 — cyclin-dependent kinase inhibitor). Phenotype resembles MEN 1 (parathyroid, pituitary, pancreatic tumours) but MENIN mutation is absent. CDKN1B encodes p27, a direct target of menin-mediated transcriptional activation in parathyroid and pituitary cells."]','A','MEN 4 is rare (~1-3% of MEN 1-like phenotype without MENIN mutations). This finding confirms that the p27 pathway is the critical downstream effector of menin tumour suppression. Mutations in CDKN2C (p18) and AIP (aryl hydrocarbon receptor-interacting protein) cause other MEN-like phenotypes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
